// The attribution lines that no commit message and no pull request description carries (.claude/rules/commit-standards.md, Body): the "Generated by [Claude Code]" footer, a link to a
// claude.ai Claude Code page, a `Co-Authored-By: Claude` line and a `Claude-Session:` trailer, in any letter case. Each is matched in the form a tool writes it (the footer as a markdown link, the link with its scheme, a trailer at the start of a line), so prose that names one passes. The CI job that checks a pull request's title
// passes the description to `pnpm commit:check --description` (.github/workflows/test.yml, commits), which reads it with this.

const ATTRIBUTION = [/generated (?:with|by) \[claude code\]/i, /https?:\/\/claude\.ai\/code/i, /^co-authored-by:\s*claude/i, /^claude-session:/i] as const;

/** The first line of `text` that holds an attribution, trimmed, or undefined. */
export function attributionLine(text: string): string | undefined {
  return text.split("\n").map((line) => line.trim()).find((line) => ATTRIBUTION.some((pattern) => pattern.test(line)));
}
